### Who Can Do What

RBAC assigns users to roles, and roles get permissions. It's simpler than per-user permission lists and scales well.

```js
// Roles: admin, editor, viewer
// Permissions: read:posts, write:posts, delete:posts, manage:users

const PERMISSIONS = {
  admin:  ['read:posts', 'write:posts', 'delete:posts', 'manage:users'],
  editor: ['read:posts', 'write:posts'],
  viewer: ['read:posts'],
};

// Authorization middleware
function authorize(...requiredPermissions) {
  return (req, res, next) => {
    if (!req.user) return res.status(401).json({ error: 'Unauthorized' });

    const userPermissions = PERMISSIONS[req.user.role] ?? [];
    const hasAll = requiredPermissions.every(p => userPermissions.includes(p));

    if (!hasAll) return res.status(403).json({ error: 'Forbidden' });
    next();
  };
}

// Usage
app.get('/api/posts', authenticate, authorize('read:posts'), getPosts);
app.post('/api/posts', authenticate, authorize('write:posts'), createPost);
app.delete('/api/posts/:id', authenticate, authorize('delete:posts'), deletePost);
app.get('/api/admin/users', authenticate, authorize('manage:users'), getUsers);
```

#### JWT with Roles

```js
// Embed role in JWT payload at login
const token = jwt.sign(
  { userId: user.id, role: user.role },
  process.env.JWT_SECRET,
  { expiresIn: '15m' }
);

// Auth middleware attaches it to req.user
req.user = jwt.verify(token, process.env.JWT_SECRET);
// req.user.role is now available to authorize() middleware
```

